35	/**
36	 * @class ImageBatch
37	 * @brief Represents a batch of images managed by NVCV.
38	 *
39	 * This class wraps the NVCVImageBatchHandle and provides a high-level interface to
40	 * manage batches of images, including querying of various properties like capacity
41	 * and number of images.
42	 */
43	class ImageBatch : public CoreResource<NVCVImageBatchHandle, ImageBatch>
44	{
45	public:
46	    using Base = CoreResource<NVCVImageBatchHandle, ImageBatch>;
47	
48	    using Base::Base;
49	    using Base::operator=;
50	
51	    ImageBatch(const ImageBatch &other)
52	        : Base(other)
53	    {
54	    }
55	
56	    ImageBatch(ImageBatch &&other) noexcept
57	        : Base(std::move(other))
58	    {
59	    }
60	
61	    ImageBatch &operator=(const ImageBatch &other)
62	    {
63	        Base::operator=(other);
64	        return *this;
65	    }
66	
67	    ImageBatch &operator=(ImageBatch &&other) noexcept
68	    {
69	        Base::operator=(std::move(other));
70	        return *this;
71	    }
72	
73	    ~ImageBatch()
74	    {
75	        this->reset();
76	    }
77	
78	    using HandleType = NVCVImageBatchHandle;
79	
80	    /**
81	     * @brief Get the capacity of the image batch, i.e., the maximum number of images it can hold.
82	     *
83	     * @return The capacity of the image batch.
84	     */
85	    int32_t capacity() const;
86	
87	    /**
88	     * @brief Get the current number of images in the image batch.
89	     *
90	     * @return The number of images.
91	     */
92	    int32_t numImages() const;
93	
94	    /**
95	     * @brief Get the type of the image batch.
96	     *
97	     * @return The type of the image batch.
98	     */
99	    NVCVTypeImageBatch type() const;
100	
101	    /**
102	     * @brief Export the underlying data of the image batch.
103	     *
104	     * @param stream The CUDA stream.
105	     * @return The image batch data.
106	     */
107	    ImageBatchData exportData(CUstream stream) const;
108	
109	    /**
110	     * @brief Export the underlying data of the image batch with a specific type.
111	     *
112	     * @tparam Data The type to cast the data to.
113	     * @param stream The CUDA stream.
114	     * @return The image batch data casted to the specified type.
115	     */
116	    template<typename Data>
117	    Optional<Data> exportData(CUstream stream) const;
118	
119	    /**
120	     * @brief Set a user-defined pointer to the image batch.
121	     *
122	     * @param ptr The pointer to set.
123	     */
124	    void setUserPointer(NVCVUserPointer ptr);
125	
126	    /**
127	     * @brief Retrieve the user-defined pointer associated with the image batch.
128	     *
129	     * @return The user pointer.
130	     */
131	    NVCVUserPointer userPointer() const;
132	
133	    /**
134	     * @brief Check if a kind is compatible with the ImageBatch class.
135	     *
136	     * @return True since all kinds are currently supported.
137	     */
138	    static bool IsCompatibleKind(NVCVTypeImageBatch)
139	    {
140	        return true;
141	    }
142	};
