157	/**
158	 * @class ImageBatchVarShape
159	 * @brief Represents a batch of images with variable shapes.
160	 *
161	 * Extends the functionality provided by the `ImageBatch` class to support batches
162	 * of images where each image might have a different shape or size.
163	 */
164	class ImageBatchVarShape : public ImageBatch
165	{
166	public:
167	    using Requirements = NVCVImageBatchVarShapeRequirements;
168	
169	    /**
170	     * @brief Calculate requirements for a variable-shaped image batch with a specific capacity.
171	     *
172	     * @param capacity The capacity for which requirements need to be calculated.
173	     * @return The requirements for creating a batch with the specified capacity.
174	     */
175	    static Requirements CalcRequirements(int32_t capacity);
176	
177	    using ImageBatch::ImageBatch;
178	    using ImageBatch::operator=;
179	
180	    ImageBatchVarShape(const ImageBatchVarShape &other) = default;
181	
182	    ImageBatchVarShape(ImageBatchVarShape &&other) noexcept = default;
183	
184	    ImageBatchVarShape &operator=(const ImageBatchVarShape &other) = default;
185	
186	    ImageBatchVarShape &operator=(ImageBatchVarShape &&other) noexcept = default;
187	
188	    ~ImageBatchVarShape() = default;
189	
190	    explicit ImageBatchVarShape(NVCVImageBatchHandle &&handle); ///< Construct from an existing NVCV handle.
191	    explicit ImageBatchVarShape(const ImageBatch &batch);       ///< Construct from an existing `ImageBatch`.
192	    explicit ImageBatchVarShape(ImageBatch &&batch);            ///< Move construct from an existing `ImageBatch`.
193	    explicit ImageBatchVarShape(const Requirements &reqs,
194	                                const Allocator &alloc = Allocator{nullptr}); ///< Construct with specific requirements.
195	    explicit ImageBatchVarShape(int32_t          capacity,
196	                                const Allocator &alloc = Allocator{nullptr}); ///< Construct with a specified capacity.
197	
198	    ImageBatchVarShape &operator=(const ImageBatch &batch);
199	    ImageBatchVarShape &operator=(ImageBatch &&batch);
200	
201	    template<class IT>
202	    void pushBack(IT itBeg, IT itend);
203	    void pushBack(const Image &img);
204	    void popBack(int32_t imgCount = 1);
205	
206	    /**
207	     *
208	     * @brief Adds images produced by the callback.
209	     *
210	     * This function appends images produced by the callback until it returns an image with a null handle.
211	     *
212	     * @param cb    A callable objects that takes no parameters and returns nvcv::Image, reference to nvcv::Image,
213	     *              an object convertible to nvcv::Image.
214	     *
215	     * @note When the callback returns NVCVImageHandle, it is assumed that the callback transfers the ownership of
216	     *       the handle reference - the reference count will not be incremented when the object is added to the batch.
217	     */
218	    template<class F, class = decltype(std::declval<F>()())>
219	    void pushBack(F &&cb);
220	
221	    /**
222	     * @brief Clear all images from the batch.
223	     */
224	    void clear();
225	
226	    /**
227	     * @brief Get the maximum size among all images in the batch.
228	     *
229	     * @return The maximum size.
230	     */
231	    Size2D maxSize() const;
232	
233	    /**
234	     * @brief Determine the unique format of the images in the batch if applicable.
235	     *
236	     * @return The unique format, or an invalid format if images have different formats.
237	     */
238	    ImageFormat uniqueFormat() const;
239	
240	    /**
241	     * @brief Access a specific image in the batch.
242	     *
243	     * @param n The index of the image.
244	     * @return The image at the specified index.
245	     */
246	    Image operator[](ptrdiff_t n) const;
247	
248	    class Iterator;
249	
250	    using ConstIterator = Iterator;
251	
252	    ConstIterator begin() const;
253	    ConstIterator end() const;
254	
255	    ConstIterator cbegin() const;
256	    ConstIterator cend() const;
257	
258	    /**
259	     * @brief Export the underlying data of the image batch.
260	     *
261	     * @param stream The CUDA stream.
262	     * @return The image batch data.
263	     */
264	    template<typename Data                                                               = ImageBatchVarShapeData,
265	             detail::EnableIf_t<detail::IsSameType<Data, ImageBatchVarShapeData>(), int> = 0>
266	    ImageBatchVarShapeData exportData(CUstream stream) const
267	    {
268	        return *ImageBatch::template exportData<ImageBatchVarShapeData>(stream);
269	    }
270	
271	    template<typename Data, detail::EnableIf_t<!detail::IsSameType<Data, ImageBatchVarShapeData>(), int> = 0>
272	    Optional<Data> exportData(CUstream stream) const
273	    {
274	        return ImageBatch::template exportData<Data>(stream);
275	    }
276	
277	    /**
278	     * @brief Check if a specific kind is compatible with the ImageBatchVarShape class.
279	     *
280	     * @param kind The kind to check.
281	     * @return True if the kind is NVCV_TYPE_IMAGEBATCH_VARSHAPE, false otherwise.
282	     */
283	    static bool IsCompatibleKind(NVCVTypeImageBatch kind)
284	    {
285	        return kind == NVCV_TYPE_IMAGEBATCH_VARSHAPE;
286	    }
287	};
