301	
302	    Iterator()                     = default;
303	    Iterator(const Iterator &)     = default;
304	    Iterator(Iterator &&) noexcept = default;
305	
306	    Iterator &operator=(const Iterator &)     = default;
307	    Iterator &operator=(Iterator &&) noexcept = default;
308	
309	    reference operator*() const;
