314	    Iterator  operator--(int);
315	    Iterator &operator--();
316	
317	    Iterator operator+(difference_type diff) const;
318	    Iterator operator-(difference_type diff) const;
319	
320	    difference_type operator-(const Iterator &that) const;
321	
322	    bool operator==(const Iterator &that) const;
323	    bool operator!=(const Iterator &that) const;
324	    bool operator<(const Iterator &that) const;
325	    bool operator>(const Iterator &that) const;
