331	    int                       m_curIndex     = 0;
332	    mutable Image             m_currentImage = {};
333	
334	    void updateCurrentItem() const;
335	    void invalidateCurrentItem();
336	
337	    friend class ImageBatchVarShape;
338	    Iterator(const ImageBatchVarShape &batch, int32_t idxImage);
339	
