32	NVCV_IMPL_SHARED_HANDLE(TensorBatch);
33	
34	/**
35	 * @brief Handle to a tensor batch object.
36	 *
37	 * Tensor batch is a container type that can hold a list of non-uniformly shaped tensors.
38	 * Rank, data type and layout must be consistent between the tensors.
39	 */
40	class TensorBatch : public CoreResource<NVCVTensorBatchHandle, TensorBatch>
41	{
42	public:
43	    using Base         = CoreResource<NVCVTensorBatchHandle, TensorBatch>;
44	    using Requirements = NVCVTensorBatchRequirements;
45	    using HandleType   = NVCVTensorBatchHandle;
46	
47	    static Requirements CalcRequirements(int32_t capacity);
48	
49	    using Base::Base;
50	    using Base::operator=;
51	
52	    TensorBatch(const TensorBatch &other)
53	        : Base(other)
54	    {
55	    }
56	
57	    TensorBatch(TensorBatch &&other) noexcept
58	        : Base(std::move(other))
59	    {
60	    }
61	
62	    TensorBatch &operator=(const TensorBatch &other)
63	    {
64	        Base::operator=(other);
